#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

class Object {
public:
    bool marked = false;
    vector<Object*> children;

    void mark() {
        if (marked) return;
        marked = true;
        for (auto child : children) child->mark();
    }
};

class GC {
    vector<Object*> heap;
public:
    Object* alloc() {
        Object* o = new Object();
        heap.push_back(o);
        return o;
    }

    void markFrom(Object* root) {
        root->mark();
    }

    void sweep() {
        auto it = remove_if(heap.begin(), heap.end(), [](Object* o) {
            if (!o->marked) { delete o; return true; }
            o->marked = false;
            return false;
        });
        heap.erase(it, heap.end());
    }

    int size() const { return heap.size(); }
};

int main() {
    GC gc;
    Object* root = gc.alloc();
    root->children.push_back(gc.alloc());
    root->children.push_back(gc.alloc());
    gc.alloc(); // orphan

    cout << "Before: " << gc.size() << endl;
    gc.markFrom(root);
    gc.sweep();
    cout << "After: " << gc.size() << endl;
    return 0;
}
